import{_ as r,c as a,o,j as n,Y as s,t as d}from"./chunks/framework.D-NV0Bun.js";const m=JSON.parse('{"title":"chgrp | x-cmd man (man1) | change group ownership","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | chgrp - change group ownership","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"chgrp | x-cmd man (man1) | change group ownership"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | chgrp - change group ownership"}]]},"headers":[],"params":{"isMan":true,"man":"chgrp","category":"man1","desc":"change group ownership"},"relativePath":"man1/chgrp.md","filePath":"man1/[man].md"}'),i={name:"man1/chgrp.md"},l={class:"visually-hidden"};function h(t,e,g,c,p,f){return o(),a("div",null,[n("h1",l,d(t.$params.man),1),e[0]||(e[0]=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>chgrp - change group ownership</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>chgrp</strong> [<em>OPTION</em>]... <em>GROUP FILE</em>... <br> <strong>chgrp</strong> [<em>OPTION</em>]... <em>--reference=RFILE FILE</em>...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Change the group of each FILE to GROUP. With <strong>--reference</strong>, change the group of each FILE to that of RFILE.</p><dl><dt><strong>-c</strong>, <strong>--changes</strong></dt><dd>like verbose but report only when a change is made</dd><dt><strong>-f</strong>, <strong>--silent</strong>, <strong>--quiet</strong></dt><dd>suppress most error messages</dd><dt><strong>-v</strong>, <strong>--verbose</strong></dt><dd>output a diagnostic for every file processed</dd><dt><strong>--dereference</strong></dt><dd>affect the referent of each symbolic link (this is the default), rather than the symbolic link itself</dd><dt><strong>-h</strong>, <strong>--no-dereference</strong></dt><dd>affect symbolic links instead of any referenced file (useful only on systems that can change the ownership of a symlink)</dd><dt><strong>--no-preserve-root</strong></dt><dd>do not treat &#39;/&#39; specially (the default)</dd><dt><strong>--preserve-root</strong></dt><dd>fail to operate recursively on &#39;/&#39;</dd><dt><strong>--reference</strong>=<em>RFILE</em></dt><dd>use RFILE&#39;s group rather than specifying a GROUP. RFILE is always dereferenced if a symbolic link.</dd><dt><strong>-R</strong>, <strong>--recursive</strong></dt><dd>operate on files and directories recursively</dd></dl><p>The following options modify how a hierarchy is traversed when the <strong>-R</strong> option is also specified. If more than one is specified, only the final one takes effect.</p><dl><dt><strong>-H</strong></dt><dd>if a command line argument is a symbolic link to a directory, traverse it</dd><dt><strong>-L</strong></dt><dd>traverse every symbolic link to a directory encountered</dd><dt><strong>-P</strong></dt><dd>do not traverse any symbolic links (default)</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><dl><dt>chgrp staff /u</dt><dd>Change the group of /u to &quot;staff&quot;.</dd><dt>chgrp -hR staff /u</dt><dd>Change the group of /u and subfiles to &quot;staff&quot;.</dd></dl><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by David MacKenzie and Jim Meyering.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>chown</strong>(1), <strong>chown</strong>(2)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/chgrp%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/chgrp\\</a>&gt; <br> or available locally via: info &#39;(coreutils) chgrp invocation&#39;</p>',20))])}const b=r(i,[["render",h]]);export{m as __pageData,b as default};
